import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for c1 in range(n):
        for c2 in range(c1+1, n):
            dc = c2 - c1
            dr = perm[c2] - perm[c1]
            vec = (dc, dr)
            if vec in vectors:
                return False
            vectors.add(vec)
    return True

